11	const PLANET_ATMOSPHERE_FRAGMENT = `
12	varying vec3 vNormal;
13	varying vec3 eyeVector;
14	uniform float atmOpacity;
15	uniform float atmPowFactor;
16	uniform float atmMultiplier;
17	uniform vec3 atmColor;
18	
19	void main() {
20	    float dotP = max(0.0, dot(vNormal, eyeVector));
21	    float factor = pow(dotP, atmPowFactor) * atmMultiplier;
22	    vec3 rimColor = mix(atmColor * 0.82, vec3(1.0), 0.28 + dotP * 0.18);
23	    gl_FragColor = vec4(rimColor, atmOpacity) * factor;
24	}
25	`;
26	
27	const CARD_HEIGHT = 3.4;
28	const CARD_WIDTH = CARD_HEIGHT * (16 / 9);
29	const MAX_PROOF_IMAGES = 12;
30	const FALLBACK_COUNT = 8;
31	const PLANET_RADIUS = 6.5;
32	const FALLBACK_COLORS = [
33	  0x6644aa, 0x4488bb, 0x44aacc, 0x228866, 0x886622, 0xaa4466, 0x664488, 0x4466aa,
34	] as const;
35	
36	function computeRadius(cardCount: number): number {
37	  const minArc = CARD_WIDTH * 1.15;
38	  return Math.max(10, (minArc * cardCount) / (2 * Math.PI));
39	}
40	
41	/**
42	 * Creates a PlaneGeometry whose vertices are bent cylindrically around the Y-axis,
43	 * so the card's edges curve inward toward the planet (local -Z = radially inward).
44	 * Each vertex at local x=lx is moved to arc position on a cylinder of curveRadius:
45	 *   newX = curveRadius * sin(lx / curveRadius)
46	 *   newZ = -curveRadius * (1 - cos(lx / curveRadius))   ← negative = toward planet
47	 */
48	function createCurvedCardGeometry(
49	  width: number,
50	  height: number,
51	  curveRadius: number,
52	): THREE.BufferGeometry {
53	  const geo = new THREE.PlaneGeometry(width, height, 20, 1);
54	  const pos = geo.attributes.position as THREE.BufferAttribute;
55	  for (let i = 0; i < pos.count; i++) {
56	    const lx = pos.getX(i);
57	    const dAngle = lx / curveRadius;
58	    pos.setX(i, curveRadius * Math.sin(dAngle));
59	    pos.setZ(i, -curveRadius * (1.0 - Math.cos(dAngle)));
60	  }
61	  pos.needsUpdate = true;
62	  geo.computeVertexNormals();
63	  return geo;
64	}
