66	function loadImageTexture(
67	  loader: THREE.TextureLoader,
68	  url: string,
69	): Promise<THREE.Texture | null> {
70	  return new Promise((resolve) => {
71	    loader.load(
72	      url,
73	      (texture) => {
74	        texture.minFilter = THREE.LinearFilter;
75	        texture.generateMipmaps = false;
76	        resolve(texture);
77	      },
78	      undefined,
79	      () => resolve(null),
80	    );
81	  });
82	}
