122	export class AboutProofRenderer {
123	  private _renderer: THREE.WebGLRenderer | null = null;
124	  private _scene: THREE.Scene | null = null;
125	  private _camera: THREE.PerspectiveCamera | null = null;
126	  private _group: THREE.Group | null = null;
127	  private _planetGroup: THREE.Group | null = null;
128	  private _geometries: THREE.BufferGeometry[] = [];
129	  private _materials: THREE.Material[] = [];
130	  private _textures: THREE.Texture[] = [];
131	  private _videoElements: HTMLVideoElement[] = [];
132	  private _rafId: number | null = null;
133	  private _resizeObserver: ResizeObserver | null = null;
134	  private _intersectionObserver: IntersectionObserver | null = null;
135	  private _rendering = false;
136	  private _disposed = false;
137	  private _canvas: HTMLCanvasElement | null = null;
138	  private _scrollProgress = 0;
139	  private _rotationStrategy: ProofRotationStrategy;
140	
141	  constructor(rotationStrategy?: ProofRotationStrategy) {
142	    this._rotationStrategy =
143	      rotationStrategy ?? new ScrollAcceleratingRotation(DEFAULT_SCROLL_ACCELERATING_CONFIG);
144	  }
145	
146	  setScrollProgress(progress: number): void {
147	    const prev = this._scrollProgress;
148	    this._scrollProgress = Math.max(0, Math.min(1, progress));
149	    this._rotationStrategy.feed(this._scrollProgress, Math.abs(this._scrollProgress - prev));
150	  }
151	
152	  async init(canvas: HTMLCanvasElement): Promise<void> {
153	    this._canvas = canvas;
154	
155	    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
156	    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
157	    renderer.setClearAlpha(0);
158	    this._renderer = renderer;
159	
160	    const scene = new THREE.Scene();
161	    this._scene = scene;
162	
163	    const w = Math.max(canvas.clientWidth, 1);
164	    const h = Math.max(canvas.clientHeight, 1);
165	    const camera = new THREE.PerspectiveCamera(65, w / h, 0.1, 1000);
166	    camera.position.set(0, 3, 22);
167	    camera.lookAt(0, 0, 0);
168	    this._camera = camera;
169	
170	    scene.add(new THREE.AmbientLight(0xffffff, 0.6));
171	    const dirLight = new THREE.DirectionalLight(0xdfe8ff, 1.4);
172	    dirLight.position.set(10, 12, 8);
173	    scene.add(dirLight);
174	
175	    const group = new THREE.Group();
176	    this._group = group;
177	    scene.add(group);
178	
179	    // Fetch works and planet textures in parallel
180	    const [worksResult, planetGroup] = await Promise.all([
181	      fetchWorksList(0, MAX_PROOF_IMAGES, null, undefined, true).catch(() => null),
182	      this._buildPlanet(),
183	    ]);
184	
185	    if (this._disposed) return;
186	
187	    if (planetGroup) {
188	      this._planetGroup = planetGroup;
189	      scene.add(planetGroup);
190	    }
191	
192	    const items = worksResult ? selectProofItems(worksResult.items, MAX_PROOF_IMAGES) : [];
193	
194	    if (items.length > 0) {
195	      const loader = new THREE.TextureLoader();
196	      const textures = await Promise.all(
197	        items.map((item) => this._loadItemMedia(loader, item)),
198	      );
199	      if (this._disposed) return;
200	      const radius = computeRadius(textures.length);
201	      textures.forEach((texture, i) => {
202	        if (texture) this._textures.push(texture);
203	        this._addCard(group, i, textures.length, texture, radius);
204	      });
205	    } else {
206	      const radius = computeRadius(FALLBACK_COUNT);
207	      for (let i = 0; i < FALLBACK_COUNT; i++) {
208	        this._addCard(group, i, FALLBACK_COUNT, null, radius);
209	      }
210	    }
211	
212	    this._syncSize();
213	    this._observeResize();
214	    this._observeVisibility();
215	  }
216	
217	  dispose(): void {
218	    this._disposed = true;
219	    this._stopRaf();
220	
221	    this._resizeObserver?.disconnect();
222	    this._resizeObserver = null;
223	
224	    this._intersectionObserver?.disconnect();
225	    this._intersectionObserver = null;
226	
227	    this._geometries.forEach((g) => g.dispose());
228	    this._geometries = [];
229	
230	    this._materials.forEach((m) => m.dispose());
231	    this._materials = [];
232	
233	    this._textures.forEach((t) => t.dispose());
234	    this._textures = [];
235	
236	    this._videoElements.forEach((v) => {
237	      v.pause();
238	      v.src = "";
239	      v.load();
240	    });
241	    this._videoElements = [];
242	
243	    this._renderer?.dispose();
244	    this._renderer?.forceContextLoss();
245	    this._renderer = null;
246	    this._scene = null;
247	    this._camera = null;
248	    this._group = null;
249	    this._planetGroup = null;
250	    this._canvas = null;
251	  }
252	
253	  private async _buildPlanet(): Promise<THREE.Group | null> {
254	    const loader = new THREE.TextureLoader();
255	    try {
256	      const [dayMap, bumpMap] = await Promise.all([
257	        new Promise<THREE.Texture>((res, rej) =>
258	          loader.load("/resource/images/texture/moon/moonmap4k.jpg", res, undefined, rej),
259	        ),
260	        new Promise<THREE.Texture>((res, rej) =>
261	          loader.load("/resource/images/texture/moon/moonbump4k.jpg", res, undefined, rej),
262	        ),
263	      ]);
264	
265	      if (this._disposed) {
266	        dayMap.dispose();
267	        bumpMap.dispose();
268	        return null;
269	      }
270	
271	      dayMap.colorSpace = THREE.SRGBColorSpace;
272	      this._textures.push(dayMap, bumpMap);
273	
274	      const geo = new THREE.SphereGeometry(PLANET_RADIUS, 48, 32);
275	      const mat = new THREE.MeshStandardMaterial({
276	        map: dayMap,
277	        bumpMap,
278	        bumpScale: 0.018,
279	        roughness: 0.42,
280	        metalness: 0.05,
281	      });
282	      this._geometries.push(geo);
283	      this._materials.push(mat);
284	      const mesh = new THREE.Mesh(geo, mat);
285	
286	      const atmGeo = new THREE.SphereGeometry(PLANET_RADIUS * 1.16, 48, 32);
287	      const atmMat = new THREE.ShaderMaterial({
288	        vertexShader: atmosphereVertexShader as string,
289	        fragmentShader: PLANET_ATMOSPHERE_FRAGMENT,
290	        uniforms: {
291	          atmOpacity: { value: 0.58 },
292	          atmPowFactor: { value: 4.3 },
293	          atmMultiplier: { value: 8.4 },
294	          atmColor: { value: new THREE.Color(0.92, 0.96, 1.0) },
295	        },
296	        blending: THREE.AdditiveBlending,
297	        side: THREE.BackSide,
298	        transparent: true,
299	        depthWrite: false,
300	      });
301	      this._geometries.push(atmGeo);
302	      this._materials.push(atmMat);
303	      const atmMesh = new THREE.Mesh(atmGeo, atmMat);
304	
305	      const group = new THREE.Group();
306	      group.add(mesh);
307	      group.add(atmMesh);
308	      return group;
309	    } catch {
310	      return null;
311	    }
312	  }
313	
314	  private _createVideoElement(url: string): HTMLVideoElement {
315	    const video = document.createElement("video");
316	    video.src = url;
317	    video.loop = true;
318	    video.muted = true;
319	    video.playsInline = true;
320	    video.crossOrigin = "anonymous";
321	    void video.play();
322	    this._videoElements.push(video);
323	    return video;
324	  }
325	
326	  private _createVideoTexture(video: HTMLVideoElement): THREE.VideoTexture {
327	    const texture = new THREE.VideoTexture(video);
328	    texture.minFilter = THREE.LinearFilter;
329	    texture.magFilter = THREE.LinearFilter;
330	    texture.generateMipmaps = false;
331	    return texture;
332	  }
333	
334	  private async _loadItemMedia(
335	    loader: THREE.TextureLoader,
336	    item: WorkApiItem,
337	  ): Promise<THREE.Texture | null> {
338	    if (item.thumbnailVideo) {
339	      const video = this._createVideoElement(item.thumbnailVideo);
340	      return this._createVideoTexture(video);
341	    }
342	    const imageUrl = item.thumbnailImage;
343	    if (imageUrl) {
344	      return loadImageTexture(loader, imageUrl);
345	    }
346	    return null;
347	  }
348	
349	  private _addCard(
350	    group: THREE.Group,
351	    index: number,
352	    total: number,
353	    texture: THREE.Texture | null,
354	    radius: number,
355	  ): void {
356	    const angle = (index / total) * Math.PI * 2;
357	    const x = radius * Math.cos(angle);
358	    const z = radius * Math.sin(angle);
359	
360	    const geo = createCurvedCardGeometry(CARD_WIDTH, CARD_HEIGHT, radius);
361	    this._geometries.push(geo);
362	
363	    const mat = createCardMaterial(
364	      texture,
365	      FALLBACK_COLORS[index % FALLBACK_COLORS.length],
366	    );
367	    this._materials.push(mat);
368	
369	    const mesh = new THREE.Mesh(geo, mat);
370	    mesh.position.set(x, 0, z);
371	    // rotation.y so the front face (+Z normal) points radially outward from center
372	    mesh.rotation.y = Math.PI / 2 - angle;
373	    group.add(mesh);
374	  }
375	
376	  private readonly _tick = (): void => {
377	    if (this._disposed || !this._rendering) return;
378	    const p = this._scrollProgress;
379	    const speed = this._rotationStrategy.next();
380	    if (this._group) this._group.rotation.y += speed;
381	    // Planet counter-rotates slowly, independent of card ring
382	    if (this._planetGroup) this._planetGroup.rotation.y += 0.0003;
383	    if (this._camera) {
384	      this._camera.position.y = 3 - p * 3;
385	      this._camera.lookAt(0, 0, 0);
386	    }
387	    if (this._renderer && this._scene && this._camera) {
388	      this._renderer.render(this._scene, this._camera);
389	    }
390	    this._rafId = requestAnimationFrame(this._tick);
391	  };
392	
393	  private _startRaf(): void {
394	    if (this._rafId !== null || this._disposed) return;
395	    this._rendering = true;
396	    this._rafId = requestAnimationFrame(this._tick);
397	  }
398	
399	  private _stopRaf(): void {
400	    this._rendering = false;
401	    if (this._rafId !== null) {
402	      cancelAnimationFrame(this._rafId);
403	      this._rafId = null;
404	    }
405	  }
406	
407	  private _syncSize(): void {
408	    const canvas = this._canvas;
409	    const renderer = this._renderer;
410	    const camera = this._camera;
411	    if (!canvas || !renderer || !camera) return;
412	    const w = canvas.clientWidth;
413	    const h = canvas.clientHeight;
414	    if (w <= 0 || h <= 0) return;
415	    renderer.setSize(w, h, false);
416	    camera.aspect = w / h;
417	    camera.updateProjectionMatrix();
418	  }
419	
420	  private _observeResize(): void {
421	    if (!this._canvas) return;
422	    this._resizeObserver = new ResizeObserver(() => this._syncSize());
423	    this._resizeObserver.observe(this._canvas);
424	  }
425	
426	  private _observeVisibility(): void {
427	    if (!this._canvas) return;
428	    this._intersectionObserver = new IntersectionObserver(
429	      (entries) => {
430	        if (entries[0]?.isIntersecting) {
431	          this._startRaf();
432	        } else {
433	          this._stopRaf();
434	        }
435	      },
436	      { threshold: 0 },
437	    );
438	    this._intersectionObserver.observe(this._canvas);
439	  }
440	}
